/**
 * Generates CSS custom properties from the Figma Variables export.
 *
 *   tokens/figma-variables.json  →  src/styles/tokens/{primitives,theme,device}.css
 *                                    tokens/tokens.json (manifest for Storybook)
 *
 * Usage: npm run tokens
 *
 * Do not edit the generated files by hand — update the export and re-run.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");
const SOURCE = path.join(ROOT, "tokens/figma-variables.json");
const OUT_DIR = path.join(ROOT, "src/styles/tokens");
const MANIFEST = path.join(ROOT, "tokens/tokens.json");

const MOBILE_MEDIA = "(max-width: 767px)";
const DARK_SELECTOR = '[data-theme="dark"]';
const LIGHT_SELECTOR = ':root,\n[data-theme="light"]';

// Variables that have no meaning in CSS (Figma component toggles etc.)
const SKIP_PREFIXES = ["components/"];

const FONT_WEIGHTS = {
  thin: 100,
  "extra light": 200,
  light: 300,
  regular: 400,
  medium: 500,
  "semi bold": 600,
  bold: 700,
  "extra bold": 800,
  black: 900,
};

const HEADER =
  "/* Generated by scripts/build-tokens.js from tokens/figma-variables.json — do not edit. */\n";

const data = JSON.parse(fs.readFileSync(SOURCE, "utf8"));
const byId = new Map(data.variables.map((v) => [v.id, v]));
const collections = new Map(data.collections.map((c) => [c.name, c]));

/* ── Helpers ───────────────────────────────────────────────── */

function cssName(figmaName) {
  const slug = figmaName
    .trim()
    .replace(/\s*\|\s*/g, "-") // "gap/120 | 24" → "gap/120-24"
    .replace(/\s+/g, "-") // "BFinance Green" → "BFinance-Green"
    .replace(/\//g, "-");
  return `--${slug}`;
}

const toByte = (c) => Math.round(c * 255);
const hex2 = (n) => n.toString(16).padStart(2, "0").toUpperCase();

function formatColor({ r, g, b, a }) {
  if (a < 0.001) return "transparent";
  if (a >= 0.999) return `#${hex2(toByte(r))}${hex2(toByte(g))}${hex2(toByte(b))}`;
  const alpha = Number(a.toFixed(3));
  return `rgba(${toByte(r)}, ${toByte(g)}, ${toByte(b)}, ${alpha})`;
}

function formatValue(variable, value) {
  const name = variable.name;
  if (variable.type === "COLOR") return formatColor(value);
  if (variable.type === "STRING") {
    if (name.startsWith("typography/weight/")) {
      const weight = FONT_WEIGHTS[value.toLowerCase()];
      if (!weight) throw new Error(`Unknown font weight "${value}" in ${name}`);
      return String(weight);
    }
    if (name.startsWith("typography/family/")) return `'${value}', sans-serif`;
    return `"${value}"`;
  }
  if (variable.type === "FLOAT") {
    const n = Number(value.toFixed(3));
    return n === 0 ? "0" : `${n}px`;
  }
  throw new Error(`Unsupported variable type ${variable.type} in ${name}`);
}

/** CSS value for one mode: var() for aliases, literal otherwise. */
function cssValue(variable, modeId) {
  const value = variable.valuesByMode[modeId];
  if (value && value.type === "VARIABLE_ALIAS") {
    const target = byId.get(value.id);
    if (!target) throw new Error(`Unresolved alias ${value.id} in ${variable.name}`);
    return `var(${cssName(target.name)})`;
  }
  return formatValue(variable, value);
}

/** Final literal value (aliases followed). Used for the Storybook manifest. */
function resolve(variable, modeName) {
  const collection = data.collections.find((c) => c.id === variable.variableCollectionId);
  const mode =
    collection.modes.find((m) => m.name === modeName) ??
    collection.modes.find((m) => m.id === collection.defaultModeId);
  const value = variable.valuesByMode[mode.id];
  if (value && value.type === "VARIABLE_ALIAS") return resolve(byId.get(value.id), modeName);
  return formatValue(variable, value);
}

function variablesOf(collectionName) {
  const collection = collections.get(collectionName);
  if (!collection) throw new Error(`Collection "${collectionName}" not found`);
  return collection.variableIds
    .map((id) => byId.get(id))
    .filter((v) => v && !SKIP_PREFIXES.some((p) => v.name.startsWith(p)))
    .sort((a, b) => groupOrder(a) - groupOrder(b));
}

// Keeps Figma's order, but pulls variables of the same "group/subgroup" together.
const groupKey = (v) => {
  const parts = v.name.split("/");
  return parts.slice(0, parts.length > 2 ? 2 : 1).join("/");
};
const firstSeen = new Map();
data.variables.forEach((v, i) => {
  if (!firstSeen.has(groupKey(v))) firstSeen.set(groupKey(v), i);
});
const groupOrder = (v) => firstSeen.get(groupKey(v));
const modeId = (collectionName, modeName) =>
  collections.get(collectionName).modes.find((m) => m.name === modeName).id;

/** Renders declarations, inserting a comment before each "group/subgroup". */
function declarations(variables, modeIdValue, indent = "  ") {
  let lines = [];
  let lastGroup = null;
  for (const v of variables) {
    const group = groupKey(v);
    if (group !== lastGroup) {
      if (lastGroup !== null) lines.push("");
      lines.push(`${indent}/* ${group} */`);
      lastGroup = group;
    }
    lines.push(`${indent}${cssName(v.name)}: ${cssValue(v, modeIdValue)};`);
  }
  return lines.join("\n");
}

function assertUniqueNames(variables) {
  const seen = new Map();
  for (const v of variables) {
    const name = cssName(v.name);
    if (seen.has(name)) throw new Error(`Name collision: "${v.name}" and "${seen.get(name)}" → ${name}`);
    seen.set(name, v.name);
  }
}

/* ── Build ─────────────────────────────────────────────────── */

const primitives = variablesOf("Primitives");
const theme = variablesOf("Theme");
const device = variablesOf("Device");
assertUniqueNames([...primitives, ...theme, ...device]);

const primitivesMode = collections.get("Primitives").defaultModeId;
const primitivesCss = `${HEADER}
:root {
${declarations(primitives, primitivesMode)}
}
`;

// Both themes declare every token, so data-theme also works on a nested element.
const themeCss = `${HEADER}
${LIGHT_SELECTOR} {
${declarations(theme, modeId("Theme", "Light"))}
}

${DARK_SELECTOR} {
${declarations(theme, modeId("Theme", "Dark"))}
}
`;

const desktopMode = modeId("Device", "Desktop");
const mobileMode = modeId("Device", "Mobile");
const mobileOnly = device.filter((v) => cssValue(v, desktopMode) !== cssValue(v, mobileMode));
const deviceCss = `${HEADER}
:root {
${declarations(device, desktopMode)}
}

@media ${MOBILE_MEDIA} {
  :root {
${declarations(mobileOnly, mobileMode, "    ")}
  }
}
`;

/** Figma name of the alias target for one mode, or null for a literal value. */
function aliasOf(variable, modeIdValue) {
  const value = variable.valuesByMode[modeIdValue];
  return value && value.type === "VARIABLE_ALIAS" ? byId.get(value.id).name : null;
}

const manifest = {
  primitives: primitives
    .filter((v) => v.type === "COLOR")
    .map((v) => ({ name: v.name, css: cssName(v.name), value: resolve(v, "Value") })),
  theme: theme.map((v) => ({
    name: v.name,
    css: cssName(v.name),
    light: { ref: aliasOf(v, modeId("Theme", "Light")), value: resolve(v, "Light") },
    dark: { ref: aliasOf(v, modeId("Theme", "Dark")), value: resolve(v, "Dark") },
  })),
};

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(path.join(OUT_DIR, "primitives.css"), primitivesCss);
fs.writeFileSync(path.join(OUT_DIR, "theme.css"), themeCss);
fs.writeFileSync(path.join(OUT_DIR, "device.css"), deviceCss);
fs.writeFileSync(MANIFEST, JSON.stringify(manifest, null, 2) + "\n");

console.log(
  `tokens: ${primitives.length} primitives, ${theme.length} theme, ${device.length} device (${mobileOnly.length} mobile overrides)`
);
